'use strict';

// MODULES //

var tape = require('tape');
var isnanf = require('@stdlib/math/base/assert/is-nanf');
var isInfinitef = require('@stdlib/math/base/assert/is-infinitef');
var PINF = require('@stdlib/constants/float32/pinf');
var NINF = require('@stdlib/constants/float32/ninf');
var EPS = require('@stdlib/constants/float32/eps');
var absf = require('@stdlib/math/base/special/absf');
var float64ToFloat32 = require('@stdlib/number/float64/base/to-float32');
var tryRequire = require('@stdlib/utils/try-require');


// VARIABLES //

var log10f = tryRequire('./../lib/native.js');
var opts = {
    'skip': (log10f instanceof Error)
};


// TESTS //

tape('main export is a function', opts, function test(t) {
    t.ok(true, __filename);
    t.strictEqual(typeof log10f, 'function', 'main export is a function');
    t.end();
});

tape('the function returns `NaN` if provided `NaN` or a negative number', opts, function test(t) {
    var v;

    v = log10f(NaN);
    t.strictEqual(isnanf(v), true, 'returns NaN');

    v = log10f(-1.0);
    t.strictEqual(isnanf(v), true, 'returns NaN');

    v = log10f(-Infinity);
    t.strictEqual(isnanf(v), true, 'returns NaN');

    t.end();
});

tape('the function returns `-infinity` if provided `+0` or `-0`', opts, function test(t) {
    var v;

    v = log10f(0.0);
    t.strictEqual(v, NINF, 'returns -Infinity');

    v = log10f(-0.0);
    t.strictEqual(v, NINF, 'returns -Infinity');

    t.end();
});

tape('the function returns `+infinity` if provided `+infinity`', opts, function test(t) {
    var v = log10f(PINF);
    t.strictEqual(v, PINF, 'returns +Infinity');
    t.end();
});

tape('the function returns `0` if provided `1.0`', opts, function test(t) {
    var v = log10f(1.0);
    t.strictEqual(v, 0.0, 'returns 0');
    t.end();
});

tape('the function evaluates the common logarithm (powers of 10)', opts, function test(t) {
    var v;

    v = log10f(10.0);
    t.strictEqual(v, 1.0, 'returns 1');

    v = log10f(100.0);
    t.strictEqual(v, 2.0, 'returns 2');

    v = log10f(0.1);
    t.strictEqual(v, -1.0, 'returns -1');

    t.end();
});

tape('the function matches Math.log10 results within tolerance', opts, function test(t) {
    var expected;
    var delta;
    var tol;
    var x;
    var y;
    var i;

    for (i = 0; i < 100; i++) {
        x = (Math.random() * 100.0) + 0.1;
        x = float64ToFloat32(x);
        y = log10f(x);
        expected = float64ToFloat32(Math.log10(x));
        delta = absf(y - expected);
        tol = 2.0 * EPS * absf(expected);
        if (tol < EPS) {
            tol = EPS;
        }
        t.ok(delta <= tol, 'within tolerance. x: ' + x + '. y: ' + y + '. expected: ' + expected + '. delta: ' + delta + '. tol: ' + tol);
    }
    t.end();
});
